{"function":"() => {
const q=s=>document.querySelector(s);
const cs=(el,props)=>{const c=getComputedStyle(el);const r=el.getBoundingClientRect();return Object.fromEntries(props.map(p=>[p,c[p]]).concat([['rect',[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)]]]))};
const P=['color','backgroundColor','fontSize','outlineStyle','outlineWidth','display','visibility','opacity','position','clip','overflow'];
const out={};
for (const s of ['.atalho-conteudo','.atalho-conteudo a','.barra-superior','.marca-govbr','.apoio-solicitacao','#cpf-apoio','#data-apoio','#descricao-apoio','#documentos-apoio','.upload-button','#documentos','.upload-label','label[for=nome]','#nome','.acao-cancelar','.acao-enviar','#data-preferencial-btn','#forma-presencial','#forma-video','#declaracao','#recurso-libras','.crumb a','td','th','.table-title','.page','.page.active','[data-previous-page]','.crumb [aria-current]','legend.label','.br-radio label','.br-checkbox label','#servico','button[data-trigger]'])
 { const e=q(s); out[s]=e?cs(e,P):null; }
return out;}"}

